    resourceControl: ai.capabilityProfile.economic * 0.4 + ai.capabilityProfile.physical * 0.3,
    manipulationCapability: ai.capabilityProfile.social,
    hackingCapability: ai.capabilityProfile.digital
  };
}

/**
