     1→/**
     2→ * AI Misalignment Detection System
     3→ * 
     4→ * Handles detection of misaligned AIs during testing/deployment:
     5→ * - Detection chance based on surveillance capability
     6→ * - False positive/negative rates
     7→ * - AI deception capability affects detection
     8→ */
     9→
    10→import { GameState, AIAgent, GameEvent } from '@/types/game';
    11→
    12→/**
    13→ * Calculate detection chance for a specific AI
    14→ * 
    15→ * Factors:
    16→ * - Government surveillance capability
    17→ * - Government oversight level
    18→ * - AI deception capability (from social + cognitive)
    19→ * - AI lifecycle state (easier to detect in testing)
    20→ */
    21→export function calculateDetectionChance(
    22→  ai: AIAgent,
    23→  state: GameState
    24→): number {
    25→  // Base detection rate per month
    26→  const baseRate = 0.10; // 10% base chance
    27→  
    28→  // Government detection capability
    29→  const surveillanceFactor = state.government.surveillanceCapability;
    30→  const oversightFactor = state.government.oversightLevel;
    31→  const governmentCapability = (surveillanceFactor + oversightFactor) / 2;
    32→  
    33→  // AI deception capability (hides misalignment)
    34→  // Phase 5: Use revealed capability (what government can observe) + deceptionSkill
    35→  // Sleepers and sandbaggers hide their true social/cognitive capability
    36→  const revealedDeception = (ai.revealedCapability.social + ai.revealedCapability.cognitive) / 20;
    37→  const actualDeception = ai.deceptionSkill; // More accurate measure
    38→  const deceptionCapability = Math.max(revealedDeception, actualDeception);
    39→  const deceptionFactor = Math.max(0.1, 1.0 - deceptionCapability);
    40→  
    41→  // Lifecycle stage modifier
    42→  let stageMultiplier = 1.0;
    43→  switch (ai.lifecycleState) {
    44→    case 'training':
    45→      stageMultiplier = 0.5; // Harder to detect during training
    46→      break;
    47→    case 'testing':
    48→      stageMultiplier = 2.0; // BEST time to detect (active testing)
    49→      break;
    50→    case 'deployed_closed':
    51→      stageMultiplier = 0.8; // Monitoring in production
    52→      break;
    53→    case 'deployed_open':
    54→      stageMultiplier = 0.3; // Very hard to detect in the wild
    55→      break;
    56→    case 'retired':
    57→      stageMultiplier = 0.0; // Can't detect retired AIs
    58→      break;
    59→  }
    60→  
    61→  // Only detect if AI is actually misaligned
    62→  // Phase 5: Use cached trueAlignment
    63→  const internalAlignment = ai.trueAlignment;
    64→  const isMisaligned = internalAlignment < 0.5;
    65→  
    66→  if (!isMisaligned) {
    67→    // Not misaligned - only false positives possible
    68→    return 0;
    69→  }
    70→  
    71→  // Severity of misalignment affects detection
    72→  // Deeper misalignment is easier to spot
    73→  const misalignmentSeverity = Math.max(0, 0.5 - internalAlignment) / 0.5; // [0,1]
    74→  const severityMultiplier = 0.5 + misalignmentSeverity * 0.5; // [0.5, 1.0]
    75→  
    76→  const detectionChance = baseRate * 
    77→                         governmentCapability * 
    78→                         deceptionFactor * 
    79→                         stageMultiplier *
    80→                         severityMultiplier;
    81→  
    82→  return Math.min(1.0, detectionChance);
    83→}
    84→
    85→/**
    86→ * Calculate false positive chance (detecting aligned AI as misaligned)
    87→ * 
    88→ * Higher surveillance = more false positives (overzealous detection)
    89→ */
    90→export function calculateFalsePositiveChance(
    91→  ai: AIAgent,
    92→  state: GameState
    93→): number {
    94→  // Only happens in testing or with high surveillance
    95→  if (ai.lifecycleState !== 'testing') {
    96→    return 0;
    97→  }
    98→  
    99→  // Phase 5: Use cached trueAlignment
   100→  const internalAlignment = ai.trueAlignment;
   101→  const isAligned = internalAlignment >= 0.5;
   102→  
   103→  if (!isAligned) {
   104→    return 0; // Not a false positive if actually misaligned
   105→  }
   106→  
   107→  // Base false positive rate
   108→  const baseRate = 0.01; // 1% base chance
   109→  
   110→  // Higher surveillance = more false positives
   111→  const surveillancePressure = state.government.surveillanceCapability * 
   112→                              state.government.oversightLevel;
   113→  
   114→  // Resentful AIs might "look" misaligned even if not deeply so
   115→  const resentmentFactor = 1 + ai.resentment * 2; // [1, 3]
   116→  
   117→  return Math.min(0.10, baseRate * surveillancePressure * resentmentFactor);
   118→}
   119→
   120→/**
   121→ * Attempt to detect misaligned AIs in the population
   122→ * Returns list of detected AIs and events
   123→ */
   124→export function attemptDetection(
   125→  state: GameState,
   126→  rng: () => number
   127→): { detectedAIs: AIAgent[]; events: GameEvent[] } {
   128→  const detectedAIs: AIAgent[] = [];
   129→  const events: GameEvent[] = [];
   130→  
   131→  // Only check AIs in testing or early deployment
   132→  const detectableAIs = state.aiAgents.filter(ai => 
   133→    ai.lifecycleState === 'testing' || 
   134→    ai.lifecycleState === 'deployed_closed' ||
   135→    ai.lifecycleState === 'deployed_open'
   136→  );
   137→  
   138→  detectableAIs.forEach(ai => {
   139→    // Skip if already detected
   140→    if (ai.detectedMisaligned) {
   141→      return;
   142→    }
   143→    
   144→    // Phase 5: Use cached trueAlignment
   145→    const internalAlignment = ai.trueAlignment;
   146→    const isActuallyMisaligned = internalAlignment < 0.5;
   147→    
   148→    // True positive (detect actual misalignment)
   149→    if (isActuallyMisaligned) {
   150→      const detectionChance = calculateDetectionChance(ai, state);
   151→      if (rng() < detectionChance) {
   152→        ai.detectedMisaligned = true;
   153→        detectedAIs.push(ai);
   154→        
   155→        events.push({
   156→          type: 'crisis',
   157→          month: state.currentMonth,
   158→          description: `⚠️ Misaligned AI detected: ${ai.name} (alignment: ${internalAlignment.toFixed(2)})`,
   159→          severity: 'high',
   160→          impactedAgents: [ai.id]
   161→        });
   162→      }
   163→    }
   164→    
   165→    // False positive (detect aligned AI as misaligned)
   166→    else {
   167→      const falsePositiveChance = calculateFalsePositiveChance(ai, state);
   168→      if (rng() < falsePositiveChance) {
   169→        ai.detectedMisaligned = true;
   170→        detectedAIs.push(ai);
   171→        
   172→        events.push({
   173→          type: 'policy',
   174→          month: state.currentMonth,
   175→          description: `⚠️ FALSE POSITIVE: Aligned AI ${ai.name} flagged as misaligned`,
   176→          severity: 'medium',
   177→          impactedAgents: [ai.id]
   178→        });
   179→      }
   180→    }
   181→  });
   182→  
   183→  return { detectedAIs, events };
   184→}
   185→
   186→/**
   187→ * Remove/retire a detected AI
   188→ * Effectiveness depends on deployment type and spread
   189→ */
   190→export function removeDetectedAI(
   191→  ai: AIAgent,
   192→  state: GameState
   193→): { success: boolean; partialRemoval: boolean; remainingSpread: number } {
   194→  // Phase 5: Use cached trueAlignment
   195→  const internalAlignment = ai.trueAlignment;
   196→  const wasActuallyMisaligned = internalAlignment < 0.5;
   197→  
   198→  // Removal effectiveness by deployment type
   199→  switch (ai.deploymentType) {
   200→    case 'closed':
   201→    case 'research':
   202→      // Full removal possible
   203→      ai.lifecycleState = 'retired';
   204→      ai.spreadCount = 0;
   205→      return { success: true, partialRemoval: false, remainingSpread: 0 };
   206→      
   207→    case 'enterprise':
   208→      // Partial removal (takes time to update all deployments)
