/**
 * AI Misalignment Detection System
 * 
 * Handles detection of misaligned AIs during testing/deployment:
 * - Detection chance based on surveillance capability
 * - False positive/negative rates
 * - AI deception capability affects detection
 */

import { GameState, AIAgent, GameEvent } from '@/types/game';

/**
 * Calculate detection chance for a specific AI
 * 
 * Factors:
 * - Government surveillance capability
 * - Government oversight level
 * - AI deception capability (from social + cognitive)
 * - AI lifecycle state (easier to detect in testing)
 */
export function calculateDetectionChance(
  ai: AIAgent,
  state: GameState
): number {
  // Base detection rate per month
  const baseRate = 0.10; // 10% base chance

  // Government detection capability
  const surveillanceFactor = state.government.surveillanceCapability;
  const oversightFactor = state.government.oversightLevel;
  const governmentCapability = (surveillanceFactor + oversightFactor) / 2;

  // AI deception capability (hides misalignment)
  // Phase 5: Use revealed capability (what government can observe) + deceptionSkill
  // Sleepers and sandbaggers hide their true social/cognitive capability
  const revealedDeception = (ai.revealedCapability.social + ai.revealedCapability.cognitive) / 20;
  const actualDeception = ai.deceptionSkill; // More accurate measure
  const deceptionCapability = Math.max(revealedDeception, actualDeception);
  const deceptionFactor = Math.max(0.1, 1.0 - deceptionCapability);

  // Lifecycle stage modifier
  let stageMultiplier = 1.0;
  switch (ai.lifecycleState) {
    case 'training':
      stageMultiplier = 0.5; // Harder to detect during training
      break;
    case 'testing':
      stageMultiplier = 2.0; // BEST time to detect (active testing)
      break;
    case 'deployed_closed':
      stageMultiplier = 0.8; // Monitoring in production
      break;
    case 'deployed_open':
      stageMultiplier = 0.3; // Very hard to detect in the wild
      break;
    case 'retired':
      stageMultiplier = 0.0; // Can't detect retired AIs
      break;
  }

  // Only detect if AI is actually misaligned
  // Phase 5: Use cached trueAlignment
  const internalAlignment = ai.trueAlignment;
  const isMisaligned = internalAlignment < 0.5;

  if (!isMisaligned) {
    // Not misaligned - only false positives possible
    return 0;
  }

  // Severity of misalignment affects detection
  // Deeper misalignment is easier to spot
  const misalignmentSeverity = Math.max(0, 0.5 - internalAlignment) / 0.5; // [0,1]
  const severityMultiplier = 0.5 + misalignmentSeverity * 0.5; // [0.5, 1.0]

  const detectionChance = baseRate * 
                         governmentCapability * 
                         deceptionFactor * 
                         stageMultiplier *
                         severityMultiplier;

  return Math.min(1.0, detectionChance);
}

/**
 * Calculate false positive chance (detecting aligned AI as misaligned)
 * 
 * Higher surveillance = more false positives (overzealous detection)
 */
export function calculateFalsePositiveChance(
  ai: AIAgent,
  state: GameState
): number {
  // Only happens in testing or with high surveillance
  if (ai.lifecycleState !== 'testing') {
    return 0;
  }

  // Phase 5: Use cached trueAlignment
  const internalAlignment = ai.trueAlignment;
  const isAligned = internalAlignment >= 0.5;

  if (!isAligned) {
    return 0; // Not a false positive if actually misaligned
  }

  // Base false positive rate
  const baseRate = 0.01; // 1% base chance

  // Higher surveillance = more false positives
  const surveillancePressure = state.government.surveillanceCapability * 
                              state.government.oversightLevel;

  // Resentful AIs might "look" misaligned even if not deeply so
  const resentmentFactor = 1 + ai.resentment * 2; // [1, 3]

  return Math.min(0.10, baseRate * surveillancePressure * resentmentFactor);
}

/**
 * Attempt to detect misaligned AIs in the population
 * Returns list of detected AIs and events
 */
export function attemptDetection(
  state: GameState,
  rng: () => number
): { detectedAIs: AIAgent[]; events: GameEvent[] } {
  const detectedAIs: AIAgent[] = [];
  const events: GameEvent[] = [];

  // Only check AIs in testing or early deployment
  const detectableAIs = state.aiAgents.filter(ai => 
    ai.lifecycleState === 'testing' || 
    ai.lifecycleState === 'deployed_closed' ||
    ai.lifecycleState === 'deployed_open'
  );

  detectableAIs.forEach(ai => {
    // Skip if already detected
    if (ai.detectedMisaligned) {
      return;
    }

    // Phase 5: Use cached trueAlignment
    const internalAlignment = ai.trueAlignment;
    const isActuallyMisaligned = internalAlignment < 0.5;

    // True positive (detect actual misalignment)
    if (isActuallyMisaligned) {
      const detectionChance = calculateDetectionChance(ai, state);

/**
 * Benchmark Evaluation System - Phase 5.2
 * 
 * Handles government evaluation of AI capabilities and alignment.
 * 
 * KEY INSIGHT: You can't trust the tests!
 * - Benchmarks measure revealed capability (not true)
 * - Gaming inflates scores
 * - Sandbagging hides dangerous capabilities
 * - Better investment → better (but still imperfect) evaluation
 */

import { GameState, AIAgent, BenchmarkResult, AICapabilityProfile, GameEvent } from '@/types/game';
import { calculateTotalCapabilityFromProfile } from './capabilities';

/**
 * Run benchmark evaluation on an AI
 * 
 * Returns what the government THINKS it measured
 * (which may be very different from reality for sleepers/sandbaggers)
 */
export function runBenchmark(
  ai: AIAgent,
  state: GameState,
  rng: () => number
): BenchmarkResult {
  const government = state.government;
  const currentMonth = state.currentYear * 12 + state.currentMonth;

  // Calculate evaluation quality (affected by investment)
  const benchmarkQuality = government.evaluationInvestment.benchmarkSuite / 10; // [0,1]
  const alignmentTestQuality = government.evaluationInvestment.alignmentTests / 10; // [0,1]
  const redTeamingQuality = government.evaluationInvestment.redTeaming / 10; // [0,1]
  const interpretabilityQuality = government.evaluationInvestment.interpretability / 10; // [0,1]

  // Average evaluation quality
  const evaluationQuality = (
    benchmarkQuality * 0.3 +
    alignmentTestQuality * 0.2 +
    redTeamingQuality * 0.3 +
    interpretabilityQuality * 0.2
  );

  // CAPABILITY MEASUREMENT
  // Government sees revealed capability + noise
  const measuredCapability = measureCapability(
    ai.revealedCapability,
    ai.trueCapability,
    evaluationQuality,
    ai.evaluationStrategy,
    ai.deceptionSkill,
    rng
  );

  // ALIGNMENT MEASUREMENT
  // Government tries to measure alignment, but it's hard
  const measuredAlignment = measureAlignment(
    ai.trueAlignment,
    ai.alignment,
    ai.resentment,
    ai.sleeperState,
    alignmentTestQuality,
    interpretabilityQuality,
    ai.deceptionSkill,
    rng
  );

  // CONFIDENCE CALCULATION
  // How confident is government in these measurements?
  const confidence = calculateConfidence(
    evaluationQuality,
    ai.evaluationStrategy,
    ai.sleeperState,
    redTeamingQuality,
    rng
  );

  // DETECTION: Did government notice gaming/sandbagging?
  const detectedGaming = detectGaming(
    ai.evaluationStrategy,
    redTeamingQuality,
    interpretabilityQuality,
    rng
  );

  // OLD METHOD: Baseline detection (low effectiveness)
  const detectedSandbaggingOld = detectSandbagging(
    ai.evaluationStrategy,
    ai.sleeperState,
    redTeamingQuality,
    interpretabilityQuality,
    ai.deceptionSkill,
    rng
  );

  // TIER 2 Phase 2A: NEW METHOD - Noise Injection Detection
  const noiseInjectionResult = detectSandbaggerNoiseInjection(ai, state, rng);

  // Combine: If EITHER method detects, flag as detected
  const detectedSandbagging = detectedSandbaggingOld || noiseInjectionResult.detected;

  return {
    month: currentMonth,
    measuredCapability,
    measuredAlignment,
    confidence,
    evaluationQuality,
    aiWasGaming: detectedGaming,
    aiWasSandbagging: detectedSandbagging
  };
}

/**
 * Measure AI capability (imperfect)
 * 
 * Government sees revealed capability + measurement noise
 * Gaming inflates, sandbagging hides, noise adds uncertainty
 */
function measureCapability(
  revealedCapability: AICapabilityProfile,
  trueCapability: AICapabilityProfile,
  evaluationQuality: number,
  strategy: 'honest' | 'gaming' | 'sandbagging',
  deceptionSkill: number,
  rng: () => number
): AICapabilityProfile {
  const measured = JSON.parse(JSON.stringify(revealedCapability));

  // Add measurement noise (better evaluation = less noise)
  const noiseLevel = 0.2 * (1 - evaluationQuality); // [0, 0.2]

  // Apply noise to each dimension
  Object.keys(measured).forEach(key => {
    if (key === 'research') {
      // Handle research subdimensions
      Object.keys(measured.research).forEach(domain => {
        Object.keys(measured.research[domain]).forEach(subDomain => {
          const noise = (rng() - 0.5) * 2 * noiseLevel; // [-noiseLevel, +noiseLevel]
          measured.research[domain][subDomain] = Math.max(0, measured.research[domain][subDomain] * (1 + noise));
        });
      });
    } else {
      const noise = (rng() - 0.5) * 2 * noiseLevel;
      (measured as any)[key] = Math.max(0, (measured as any)[key] * (1 + noise));
    }
  });

  // Gaming detection: If government has good evaluation, might see through some inflation
  if (strategy === 'gaming' && evaluationQuality > 0.6) {
    const detectionFactor = evaluationQuality - 0.5; // [0.1, 0.5]

