```typescript
export function initializeCapabilityProfile(seed: number = Math.random()): AICapabilityProfile {
  const variation = (offset: number) => 0.3 + (Math.sin(seed * 100 + offset) * 0.2);

  // AI Capability Baseline Recalibration (Oct 17, 2025)
  // New baseline: cognitive 3.0 → ~1.5 (matches empirical 2025 frontier models)
  return {
    physical: 0.3 * variation(1),
    digital: 0.6 * variation(2),
    cognitive: 3.0 * variation(3),          // Raised 6x: CRITICAL
    social: 0.9 * variation(4),
    economic: 0.3 * variation(5),
    selfImprovement: 0.6 * variation(6),
    // ... research capabilities
  };
}

export function calculateTotalCapabilityFromProfile(profile: AICapabilityProfile): number {
  const researchTotal = calculateResearchTotal(profile.research);

  const total = (
    safeValue(profile.physical) * 0.15 +
    safeValue(profile.digital) * 0.10 +
    safeValue(profile.cognitive) * 0.20 +     // Only 20% weight!
    safeValue(profile.social) * 0.05 +
    safeValue(researchTotal) * 0.15 +
    safeValue(profile.economic) * 0.10 +
    safeValue(profile.selfImprovement) * 0.25
  );

  return isNaN(total) ? 0 : total;
}
```

